  "title": "Ngày mưa trong nhà ở Đà Lạt",
  "summary": "Trời mưa thì mình rút vào trong: chùa, dinh thự, nhà ga và những quán ngon có mái che, vẫn trọn vị Đà Lạt mà không ướt áo.",
  "stops": [
    {
      "poi_id": "p8",
      "kind": "activity",
      "must_do_id": null,
      "note": "Mưa ngoài kia kệ mưa, mái chùa vẫn che cho mình ngắm khảm sành rực rỡ."
    },
    {
      "poi_id": "p11",
      "kind": "activity",
      "must_do_id": null,
      "note": "Dinh III kín gió, vừa tránh mưa vừa xem đồ xưa, hợp với người thích đi chậm."
    },
    {
      "poi_id": "p80",
      "kind": "meal",
      "must_do_id": null,
      "note": "Bữa trưa nóng hổi trong quán, bánh canh cua làm ấm bụng ngày mưa."
    },
    {
      "poi_id": "p136",
      "kind": "activity",
      "must_do_id": null,
      "note": "Nhà ga cổ có mái che, ngắm kiến trúc xưa mà không sợ ướt giày."
    },
    {
      "poi_id": "p37",
      "kind": "activity",
      "must_do_id": null,
      "note": "Ngồi trong quán cà phê, nhìn mưa rơi ngoài cửa kính, chậm rãi đúng ý."
    },
    {
      "poi_id": "p157",
      "kind": "meal",
      "must_do_id": null,
      "note": "Tối đến quán nem nướng ngồi bàn đàng hoàng, ăn no rồi về nghỉ."
    }
  ]
}
